import java.util.Scanner;

public class Main {
    static long[] digitPattern = new long[20];
    static int minStepCount;

    static long getMostSignificantDigit(long number, int[] length) {
        length[0] = 0;
        while (number >= 10) {
            number /= 10;
            length[0]++;
        }
        return number;
    }

    static void searchMinMoves(long currentValue, int steps) {
        if (steps >= minStepCount) return;
        if (currentValue == 0) {
            minStepCount = steps;
            return;
        }
        int[] lenArr = new int[1];
        int firstDigit = (int) getMostSignificantDigit(currentValue, lenArr);
        int len = lenArr[0];

        searchMinMoves(Math.abs(currentValue - digitPattern[len] * firstDigit), steps + firstDigit * (len + 1));
        if (firstDigit - 1 > 0)
            searchMinMoves(Math.abs(currentValue - digitPattern[len] * (firstDigit - 1)), steps + (firstDigit - 1) * (len + 1));
        if (firstDigit > 1)
            searchMinMoves(Math.abs(digitPattern[len + 1] - currentValue), steps + (len + 2));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        digitPattern[0] = 1;
        for (int i = 1; i <= 18; i++) {
            digitPattern[i] = digitPattern[i - 1] * 10 + 1;
        }
        minStepCount = Integer.MAX_VALUE;
        searchMinMoves(n, 0);
        System.out.println(minStepCount);
        sc.close();
    }
}
